mapper.update:
UPDATE durable_task_runs
SET heartbeat_at = #{heartbeatAt},
    lease_expires_at = #{leaseExpiresAt},
    updated_at = #{heartbeatAt}
WHERE id = #{id}
  AND lease_owner = #{leaseOwner}
  AND status IN ('RUNNING', 'CANCELLING')

UPDATE durable_task_runs SET status = 'RETRY_WAIT', step = 'RETRY_WAIT', available_at = #{now}, lease_owner = NULL, lease_expires_at = NULL, heartbeat_at = NULL, error_code = 'PROCESS_INTERRUPTED', error_message = '上次执行因进程中断，正在从安全点恢复。', updated_at = #{now} WHERE status IN ('RUNNING', 'CANCELLING') AND lease_expires_at <= #{now} AND resumable = 1 AND attempt < max_attempts
AND lease_owner NOT IN
#{excludedLeaseOwner}

UPDATE durable_task_runs SET status = 'INTERRUPTED', step = 'INTERRUPTED', completed_at = #{now}, duration_ms = CASE WHEN started_at IS NULL THEN 0 ELSE MAX(0, #{now} - started_at) END, lease_owner = NULL, lease_expires_at = NULL, heartbeat_at = NULL, error_code = 'RECOVERY_EXHAUSTED', error_message = #{message}, updated_at = #{now} WHERE status IN ('RUNNING', 'CANCELLING') AND lease_expires_at <= #{now} AND (resumable = 0 OR attempt >= max_attempts)
AND lease_owner NOT IN
#{excludedLeaseOwner}

UPDATE durable_task_runs
SET step = #{step},
    progress_current = #{progressCurrent},
    progress_total = #{progressTotal},
    current_item = #{currentItem},
    checkpoint_json = #{checkpointJson},
    updated_at = #{updatedAt}
WHERE id = #{id}
  AND lease_owner = #{leaseOwner}
  AND status IN ('RUNNING', 'CANCELLING')

mapper.delete:
DELETE FROM durable_task_runs
WHERE id = #{id}
  AND status NOT IN ('QUEUED', 'RUNNING', 'RETRY_WAIT', 'CANCELLING')

DELETE FROM durable_task_runs
WHERE id IN (
    SELECT id FROM knowledge_folder_runs
    WHERE scope_type = #{scopeType}
      AND ((#{scopeId} IS NULL AND scope_id IS NULL) OR scope_id = #{scopeId})
      AND id != #{excludedId}
)
  AND status NOT IN ('QUEUED', 'RUNNING', 'RETRY_WAIT', 'CANCELLING')
